"""
	Approximates supersonic shock stand-off distance for the stagnation
	point of an obstacle with equivalent radius R_n

    Input variables:
        R_n 	:   Obstacle radius
        rho_inf :   Freestream density
        rho_s 	:   Density at point immediately behind shock
	"""
def shock_standoff(R_n: Any, rho_inf: Any, rho_s: Any) -> object {
    delta = R_n * (rho_inf / rho_s);
    return delta;
}

"""
    :param geo_list: list of (geo, geo_id) pair (smallest first)
                     e.g. [(block%20group, *), (state, 01), (county, 02), (track, *), ]
    :return: url for geo query
    """
def get_geo_url(geo_list: Any) -> object {
    total_level = len(geo_list);
    url = "";
    for i in range(total_level) {
        (level, val) = geo_list[i];
        if (i == 0) {
            url += "&for=%s:%s" % (level, val);
        } else {
            url += "&in=%s:%s" % (level, val);
        }
    }
    return url;
}

