"""Find number of step combinations for maximum of three steps at a time

    :param step Number of steps left
    :return     Number of step combinations

    """
def triple_step_combinations(step: Any) -> object {
    if (step < 0) {
        return 0;
    } elif (step == 0) {
        return 1;
    }
    return (
        triple_step_combinations((step - 3))
        + triple_step_combinations((step - 2))
        + triple_step_combinations((step - 1))
    );
}

"""Returns True is test_val is between a and b"""
def test_if_between(a: Any, b: Any, test_val: Any) -> object {
    if (a < b) {
        return (a <= test_val <= b);
    } else {
        return (b <= test_val <= a);
    }
}

